SELECT *
FROM oa_contract



            AND contract_id = #{query.contractId}


            AND contract_type = #{query.contractType}


            AND status = #{query.status}


            AND risk_level = #{query.riskLevel}


            AND contract_no LIKE CONCAT('%', #{query.contractNo}, '%')


            AND contract_name LIKE CONCAT('%', #{query.contractName}, '%')


            AND counterparty_name LIKE CONCAT('%', #{query.counterpartyName}, '%')


    AND del_flag = '0'

ORDER BY create_time DESC
